INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (6, 'Baku', 'Hotel', 'Day Trip', NULL, NULL, NULL, '09:00 – Leaving Baku to Guba(1 way takes 3 hours) \n  \n 12:00 – Reaching to Guba and visiting the Guba Genocide Memorial Complex. \n  The mass grave, discovered accidentally during the excavations for construction purposes in the town of Guba in 2007, was a clear evidence of the genocide of the Muslim population of Guba, committed by Armenian armed forces under Bolshevik name in May 1918. The area is wonderful on the left side of river Qudiyal-chay. Here you can see the part of history of our nation and relax with nature \n  \n 12:30 – Lunch break \n  \n 15:00 - Visiting Qecresh Forest  \n  - Qechresh Forest, also known as Gachresh Forest, is one of the largest forests in Azerbaijan, located near the town of Quba. Renowned for its dense foliage and majestic landscape, it features a rich biodiversity and is a habitat for various plant species and wildlife. The forest''s high altitude and clean, fresh air make it a perfect spot for those looking for outdoor adventures or simply to relax . \n   \n 17:00 - Leave Guba to Baku \n  \n  20:00 - Dinner Break (if included) \n  \n  21:00 – Drop to Hotel \n  \n Overnight at Hotel', 71.0, 76.0, 80.0, 85.0, 195.0, 265.0, 324.0, 354.0, 354.0, 20.0, 47.0);
