INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (13, 'Baku', 'Baku', 'Day Trip', NULL, NULL, NULL, '09:00 – Leaving Baku to Gabala (1 way x 4.5 hrs) \n  \n 13:00 – Reaching to Gabala \n  \n 13:30 – Lunch break \n  \n 14:30 – Visiting Tufandagh Mountains Resort  \n - Tufandagh is a mountain peak of the Greater Caucasus range, located in the Qusar District of Azerbaijan. With an elevation of 4,191 metres (13,750 ft) above sea level, it third highest mountain in Azerbaijan. Visit to Nohur lake, guests enjoy with Panoramic Nature view (Located about 5 km. east of the Gabala city, the lake is surrounded by the forests and high mountains called Yumru, Goydag and Gulluburun. The lake covers 240 ha in total and has the maximum depth of 24 meters. The Nohur lake has very clear water thanks to the fresh water sources spilt into the lake. Apart from the small seasonal water supply coming from the mountains of Caucasus, Damiraparan and Vandam rivers also flow to the lake. \n   \n 17:00 – Leaving Gabala to Baku \n   \n 21:00 – Dinner Break (if included) \n   \n 22:00 – Drop to the Hotel \n   \n Overnight in Baku', 71.0, 76.0, 80.0, 85.0, 195.0, 295.0, 354.0, 412.0, 412.0, 20.0, 47.0);
