INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (27, 'Baku', 'Baku', 'Day Trip', NULL, NULL, NULL, '09:00 – Leaving Baku to Gobustan (1 way x 45 mins) \n  \n  10:00 – Reaching to Gobustan \n - Visit Gobustan National Park, a UNESCO World Heritage site known for its ancient petroglyphs, rock formations, and archaeological heritage dating back more than 40,000 years. The open-air museum offers insights into prehistoric human life, hunting traditions, and early settlements. After exploring the site, continue to the nearby Mud Volcanoes—one of the largest mud volcano fields in the world. The unique grey, lunar-like landscape and constantly bubbling mud pools create an unforgettable natural experience and an excellent spot for photos. \n   \n  11:00 – Leaving Gobustan to Gabala (1 way x 4,5 hrs) \n   \n 12:30 – Lunch break  \n   \n 15:30 - Reaching Gabala & visiting Tufandagh Mountain Resort  \n   \n  18:00 – Leaving Gabala to Baku \n   \n 22:30 – Dinner break (if included) \n   \n 23:30 – Drop to the hotel \n   \n Overnight in Baku', 77.0, 83.0, 101.0, 112.0, 300.0, 207.0, 412.0, 471.0, 471.0, 20.0, 47.0);
