INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (30, 'Baku', 'Sheki', 'Overnight', NULL, NULL, NULL, '08:00 – Depart from Baku to Sheki (1 way x 5,5 hrs) \n  \n  13:30 – Lunch Break \n   \n 15:00 – Check-in to the Hotel 16:00 -Visit Church of Kish \n  - Kish is one of the oldest villages in present-day Azerbaijan and is most known for the ancient Church of Saint Elisha from the period of Caucasian Albania. The current structure was built between the 10th–12th centuries. According to scholars, it stands on the original site where St. Elisha founded the first Christian church in the region, making it one of the earliest spiritual centers in the Caucasus. \n  \n  17:00 – Visit Sheki Fortress \n  \n  - Sheki Fortress was constructed to protect the historic center, which is now recognized as a UNESCO World Heritage Site. The original fortification walls once reached 8 meters in height and 2 meters in thickness, with defensive towers and arched gates. Although parts were destroyed, several sections have been preserved and restored. \n  \n  17:00 – Explore Sheki Karavansaray \n  \n  - This historic caravanserai served as a secure lodging place for merchants traveling along the Silk Road with their animals and trade goods. Today, it stands as one of the most iconic and culturally significant architectural landmarks in Sheki. \n  \n  18:00 Traditional Sheki Halva Tasting \n  \n - Experience Sheki’s famous halva — one of the region’s most well-known traditional sweets. It remains a highlight of local cuisine and a must-try specialty for visitors. \n  \n  18:30 – Dinner break (if included) \n  \n  19:30 – Drop at the Hotel \n  \n  Overnight in Sheki', 113.0, 119.0, 137.0, 148.0, 325.0, 442.0, 709.0, 677.0, 677.0, 40.0, 65.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (31, 'Baku', 'Baku', 'Day Trip', NULL, NULL, NULL, '08:00 – Leaving Baku to Ganja (1 way x 5.5 hours) \n  \n 13:00 – Lunch Break \n  \n 13:35 – Visit Nizami Ganjavi Mausoleum & Museum \n  - The mausoleum of the great Azerbaijani poet Nizami Ganjavi is one of Ganja’s most important historical landmarks. Restored in 1990–1991, the complex is now a protected heritage site. The lower chambers contain the poet’s crypt, while the surrounding square features sculptures inspired by Nizami’s famous literary work, Khamsa. \n  - In front of the mausoleum is the Nizami Ganjavi Museum, displaying original and replica manuscripts, rare miniatures, monographs, and books dedicated to the poet. Items exhibited include works preserved in world-renowned libraries and museums across Austria, Germany, Russia, the UK, Egypt, France, and the United States. The museum also includes a conference hall hosting cultural and educational programs. \n  \n 14:00 – Walk along Javad Khan Street \n  - One of Ganja’s main pedestrian streets, Javad Khan Street is named after the last khan of Ganja. Known for its historical red-brick architecture, the street blends renovated and original buildings, preserving traditional patterns and ornamentation. It is a lively, scenic location popular with both locals and visitors — ideal for strolling, sightseeing, and photography. \n   \n 15:00 – Visit Nizami Ganjavi Square & Javad Khan Tomb \n  - This area holds great cultural and historical importance. The Javad Khan Mausoleum commemorates the bravery of Ganja’s last ruler, who died defending the city. The memorial stands as a meaningful tribute to past struggles and the resilience of the region. \n   \n 16:00 – Leaving Ganja to Baku (1 way x 5,5 hours) \n   \n 21:00 – Dinner Break (if included) \n   \n 22:00 – Drop to the Hotel \n   \n Overnight in Baku', 77.0, 83.0, 101.0, 112.0, 265.0, 354.0, 412.0, 471.0, 471.0, 20.0, 47.0);
