INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (38, 'Gabala', 'Gabala', 'Day Trip', NULL, NULL, NULL, '08:00 – Leaving Gabala to Sheki (1 way x 1.5 hrs) \n  \n  09:30 – Arrive in Sheki \n  \n  09:45 – Visit Church of Kish \n  - Kish is one of the oldest villages in Azerbaijan, famous for its ancient Church of Saint Elisha, dating from the 10th–12th centuries. Scholars believe the church stands on the original site founded by St. Elisha, making it one of the oldest spiritual centers in the Caucasus. \n  \n  10:45 – Explore Sheki Fortress \n  - Built to protect the historic city center (now a UNESCO World Heritage Site), the fortress originally had 8-meter-high walls and 2-meter-thick fortifications with defensive towers and arched gateways. Some parts have been restored, allowing visitors to experience its historic significance. \n  \n  11:45 – Visit Sheki Karavansaray \n  - This Silk Road caravanserai historically provided safe lodging for merchants traveling with camels and goods. Today, it is one of Sheki’s iconic landmarks and a must-see cultural site. \n  \n  12:30 – Taste Sheki Halva \n  - Enjoy Sheki’s famous traditional halva — one of the region’s most beloved culinary specialties. \n  \n  13:00 – Lunch Break  \n  \n  14:00 – Arrive back in Gabala  \n  \n  18:00 – Dinner Break (if included)  \n  \n  19:00 – Drop to the Hotel \n  \n  Overnight in Gabala', 30.0, 36.0, 47.0, 59.0, 100.0, 120.0, 147.0, 177.0, 177.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (39, 'Baku', 'Baku', 'Day Trip', NULL, NULL, NULL, '09:00 – Leaving Baku to Beshbarmag (1 way x 1.5 hrs) \n  \n 10:30 – Arrive at Beshbarmag Mountain  \n  \n 10:45 – Visit Beshbarmag Mountain \n  • Beshbarmag (literally “Five Fingers Mountain”) stands at about 382 m / ≈ 500 m above sea level and is a famous natural and spiritual landmark near the Caspian Sea.  \n  • The hike/trail from the car park to the rocky peak (or sacred “pir / shrine” zone) is fairly accessible; many visit to enjoy the views of the sea and surrounding plains, or for its local spiritual significance.  \n   \n 12:30 – Leaving Beshbarmag to Baku (1 way x 1,5 hrs) \n   \n 14:00 – Lunch Break  \n   \n 15:00 – Drop to the Hotel  \n    \n  Overnight in Baku', 30.0, 36.0, 47.0, 59.0, 165.0, 236.0, 295.0, 354.0, 354.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (40, 'Baku', 'Baku', '1 Way Transfer', NULL, NULL, NULL, '08:30 – Leaving Baku to Red Bridge (1 way x 6,5 hrs) \n  \n  14:00 – Lunch Break \n  \n  14:15 – Visit and explore Red Bridge - The Red Bridge is a historical architectural monument built over the Khrami (or “Khram”) river, known for its red brick construction. The structure dates back to the 12th/17th centuries and has four spans. In the past, the area around the bridge included caravanserai style accommodations for merchants traveling along major trade routes.  \n  \n  15:00 – Leaving Red Bridge back to Baku  \n  \n  21:00 – Dinner Break (if included) (1 way x 6,5 hrs) \n  \n  22:00 – Drop to the Hotel  \n  \n  Overnight in Baku', 65.0, 71.0, 112.0, 124.0, 324.0, 412.0, 471.0, 530.0, 530.0, 40.0, 47.0);
