INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (42, 'Gabala', 'Gabala', 'Day Trip', NULL, NULL, NULL, '08:00 – Leaving Gabala to Sheki (1 way x 1.5 hrs) \n  \n  09:30 – Arrive at Sheki  \n  \n  - Church of Kish – An ancient church dating back to the 10–12th centuries, one of the oldest spiritual centers in the Caucasus. \n  - Sheki Fortress – Historic fortress with partial restoration, originally built to protect the city center. \n  - Sheki Karavansaray – A Silk Road inn used by merchants, now a cultural landmark. \n  - Sheki Halva Tasting – Traditional sweet specialty, highly recommended for visitors. \n  \n  12:30 - Lunch Break  \n  \n  13:30 – Leaving Sheki to Ganja (1 way x 2.5 hrs) \n  \n  16:00 – Arrive at Ganja \n  \n  - Nizami Ganjavi Mausoleum – Honoring Azerbaijan’s famous poet, featuring a beautifully restored monument and crypt. \n  - Javad Khan Tomb – Memorial to Ganja’s last khan, who defended the city; a historical landmark. \n  - Javad Khan Street – Central street showcasing Ganja’s architectural heritage and cultural vibe. \n  \n  18:00 – Leaving Ganja to Gabala \n  \n  20:30 – Dinner Break (if included)  \n  \n  21:30 – Drop to the hotel \n  \n Overnight in Gabala', 71.0, 77.0, 89.0, 101.0, 147.0, 165.0, 177.0, 206.0, 206.0, 20.0, 47.0);
