INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (137, 'Hotel', 'Baku', 'Private Transfer', NULL, NULL, NULL, '10:00 – Leaving Hotel to Heydar Aliyev Center & “I LOVE BAKU” Sign Photostop \n  - If it’s first time of your arrival to Baku, just be aware of that  \n  from the bird view you can clearly see the Heydar Aliyev’s  \n  Signature on the Heydar Aliyev’s Center design. It’s a wave-like \n  building rises from a bed of concrete. Its immobile white walls  \n  look as though they have been frozen mid-ripple. The abstract  \n  architecture is unlike anything else in the capital city. The  \n  Heydar Aliyev Center, which was designed by renowned architect Zaha Hadid. \n   \n  12:00 Baku boulevard tour starts along the Baku Boulevard followed by:  \n  \n  -Carpet Museum  \n  \n  -Mini Venice of Baku \n  \n  -Deniz Mall  \n  \n  -Ferries Wheel  \n  \n  -Carpet Museums \n  \n  -Cristal Hall \n   \n  13:00 - Lunch Break \n  \n  14:00 - Old City tour starts from Shamakhi Gates followed by below places (Photo stop): \n  - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture. \n  - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist. \n  - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade. \n  - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture. \n  - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City. \n  - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher. \n  - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books. \n  - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture. \n   \n  15:00 Fountain Square walking tour \n - The square is a public gathering place, especially after business hours and during the weekend. It is an attractive tourist destination with many boutiques, restaurants, shops, hotels and passage. This is one of the most crowd and lively places in the city. \n   \n  18:00 – Dinner Break (if included) \n   \n 19:00 –Drop to Hotel \n   \n Overnight in Baku', 35.0, 38.0, 40.0, 50.0, 88.0, 147.0, 177.0, 206.0, 206.0, 20.0, 47.0);
