INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (143, 'Airport Pick up', 'Shahdag', 'Overnight', NULL, NULL, NULL, 'Pick-up from GYD Airport and leaving Baku to Shahdag ( 1 way x 4 hrs) \n  \n  14:00 – Arrive in Shahdag \n  \n  12:00 – Visiting Qecresh Forest (photostop) \n  - Qechresh Forest, also known as Gachresh Forest, is one of the largest forests in Azerbaijan, located near the town of Quba. Renowned for its dense foliage and majestic landscape, it features a rich biodiversity and is a habitat for various plant species and wildlife. The forest''s high altitude and clean, fresh air make it a perfect spot for those looking for outdoor adventures or simply to relax . \n   \n  12:30 – Lunch Break  \n  \n  13:30 – Reaching to Shahdag and visit Shahdag Mountain Resort \n  - Shahdag is the highest part of the side ridge in the territory of the Republic of Azerbaijan. It is separated from the Kyzylgaya plateau by the Gusar river valley. Composed of sediments of the Jurassic and Cretaceous systems. Its height is up to 4243 meters (Shahdag peak). There are alpine and subalpine meadows, glaciers with an area of more than 1 square km. \n   - Discover the wonders of Shahdag, a land of ancient glaciers, majestic valleys, and stunning mountain lakes! Designed with avid outdoor enthusiasts in mind, Shahdag Mountain Resort offers an array of thrilling activities throughout the year. Picture yourself zooming down the slopes, feeling the crisp mountain air on your face as you carve your way through powdery snow. And for those seeking an adrenaline rush of a different kind, don''t miss the Shahdag Coaster, an exhilarating roller coaster that takes you on a wild ride through the breathtaking mountain scenery. \n   \n  15:00 - Check-in to the Hotel  \n  \n  18:00 - Dinner Break (if included) \n  \n  19:00 – Drop to Hotel \n  \n  Overnight in Shahdag', 91.0, 91.0, 114.0, 114.0, 255.0, 383.0, 504.0, 618.0, 1.0, 40.0, 65.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (144, 'Shahdag', 'GYD Airport', 'Private Transfer', NULL, NULL, NULL, '09:00 am – Leaving Shahdag to GYD Airport. \n   \n - Drop off at GYD Airport based on flight time.', 88.0, 88.0, 118.0, 118.0, 165.0, 295.0, 354.0, 412.0, 1.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (145, 'Airport Pick up', 'Gabala', 'Overnight', NULL, NULL, NULL, '- Pick-up from GYD Airport and leaving Baku to Gabala ( 1 way x 5 hrs) \n   \n 13:00 – Reaching to Gabala \n  \n  14:00 – Lunch break \n  \n  15:00 – Check-in to the Hotel \n   \n   16:00 - Visiting Tufandagh Mountains Resort  \n  - Tufandagh is a mountain peak of the Greater Caucasus range, located in the Qusar District of Azerbaijan. With an elevation of 4,191 metres (13,750 ft) above sea level, it third highest mountain in Azerbaijan. Visit to Nohur lake, guests enjoy with Panoramic Nature view (Located about 5 km. east of the Gabala city, the lake is surrounded by the forests and high mountains called Yumru, Goydag and Gulluburun. The lake covers 240 ha in total and has the maximum depth of 24 meters. The Nohur lake has very clear water thanks to the fresh water sources spilt into the lake. Apart from the small seasonal water supply coming from the mountains of Caucasus, Damiraparan and Vandam rivers also flow to the lake. \n   \n  18:00 – Dinner Break (if included) \n  \n  19:00 – Drop to the Hotel \n  \n  Overnight in Gabala', 91.0, 91.0, 114.0, 114.0, 255.0, 383.0, 504.0, 618.0, 1.0, 40.0, 65.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (146, 'Gabala', 'GYD Airport', 'Private Transfer', NULL, NULL, NULL, '09:00 am – Leaving Gabala to GYD Airport. \n   \n - Drop off at GYD Airport based on flight time.', 88.0, 88.0, 118.0, 118.0, 165.0, 295.0, 354.0, 412.0, 1.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (147, 'Hotel', 'Private Transfer', 'Private Transfer', NULL, NULL, NULL, '10:00 – Leaving Hotel Panaromic city tour which starts with panoramic full evening city view of Baku followed by: \n  - Highland Park -Which is the highest point in the Azerbaijani capital, opening a panoramic view of the city and its bay. The city''s residents and visitors often come here to see a bird''s eye view of Baku, and just have a walk. The Upland Park can be reached by cable railway (funicular) in 7-8 minutes from the boulevard or by climbing up the endless stone stairs. \n  - Flame Towers -The city''s tallest building. The height of 182 m. Flame Towers - consisting of three high-rise buildings in the complex. \n   \n  13:00 – Lunch Break \n   \n 14:00 – Shopping Tour - Guests are free to choose any of below Shopping Malls:  \n  \n  • Park Boulevard Mall \n  \n  • Port Baku Mall  \n  \n  • Ganjlik Mall \n  \n  • Nargiz Mall \n  \n  • Deniz Mall \n  \n  • 28th Mall \n  \n  • Crescent Mall \n   \n  - Drop off at GYD Airport based on flight time', 65.0, 65.0, 85.0, 85.0, 106.0, 1.0, 1.0, 1.0, 1.0, 20.0, 47.0);
