INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (156, 'Baku', 'Shamakhi', 'Day Trip', NULL, NULL, NULL, '09:00 – Leaving Baku to Shamakhi (1 way x 2 hrs) \n  \n 11:30 – Arrive to Shamakhi \n  \n 12:00 -  Alpaca Farm is located in the Shamakhi district, close to the Meyseri vineyards, surrounded by picturesque mountains and green pastures. For the construction of the farm, the Shamakhi district was not chosen by chance. Most of this area is a resort area with multiple springs. It is rich in mountain forests and meadows, and is located in a zone of moderate humidity, which makes it ideal for keeping alpacas.In addition, on the territory of the farm there will be souvenir shops with handmade dolls, stationery, bags of fertilizer, branded merch (T-shirts, hoodies, caps). \n  \n 12:30 – Lunch Break \n  \n 15:00 -Leave Shamakhi to Baku \n  \n 18:00 – Dinner Break (if included) \n  \n 19:30 – Drop to Hotel \n  \n Overnight in Shamakhi', 41.0, 47.0, 53.0, 65.0, 165.0, 236.0, 295.0, 354.0, 354.0, 20.0, 47.0);
