INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (294, 'Baku', 'Baku', 'Day trip', NULL, NULL, NULL, '09:00 – Leaving Baku to Shamakhi (1 way x 2.5 hrs) \n  \n  11:30 – Arrive in Shamakhi \n  - Visit to Shamakhi Juma Mosque - one of the oldest mosques in the Caucasus, originally built in the 8th century and restored over time. A significant example of Islamic architecture. \n   \n  - Yeddi Gumbaz Mausoleum (Photo Stop) - Explore the historical mausoleum complex with panoramic views and photo opportunities. \n   \n  12:30 – Lunch Break \n   \n  13:30 – Leaving Shamakhi to Gabala (1 way takes 2 hours) \n  \n  15:30 – Arrive in Gabala \n  Explore Gabala, a picturesque region surrounded by mountains. Highlights include: \n   \n  - Tufandag Mountains – Scenic mountain range offering breathtaking views. \n  - Nohur Lake – Surrounded by forests and mountains, ideal for photography and short nature walks. \n  - Gabala City Center – Leisure time for walking or exploring local shops and attractions. \n   \n  17:00 – Leaving Gabala to Baku \n  \n  20:00 – Dinner Break (if included) \n  \n  21:00 –Drop to Hotel \n  \n  Overnight in Baku', 71.0, 71.0, 94.0, 94.0, 165.0, 295.0, 354.0, 412.0, 1.0, 20.0, 47.0);
