INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (296, 'Airport Pick up', 'Shahdag', 'Overnight', NULL, NULL, NULL, 'Pick-up from GYD Airport and leaving Baku to Shahdag ( 1 way x 4 hrs) \n  \n  14:00 – Arrive in Shahdag \n  \n  12:00 – Visiting Qecresh Forest (photostop) \n  - Qechresh Forest, also known as Gachresh Forest, is one of the largest forests in Azerbaijan, located near the town of Quba. Renowned for its dense foliage and majestic landscape, it features a rich biodiversity and is a habitat for various plant species and wildlife. The forest''s high altitude and clean, fresh air make it a perfect spot for those looking for outdoor adventures or simply to relax . \n   \n  12:30 – Lunch Break  \n  \n  13:30 – Reaching to Shahdag and visit Shahdag Mountain Resort \n  - Shahdag is the highest part of the side ridge in the territory of the Republic of Azerbaijan. It is separated from the Kyzylgaya plateau by the Gusar river valley. Composed of sediments of the Jurassic and Cretaceous systems. Its height is up to 4243 meters (Shahdag peak). There are alpine and subalpine meadows, glaciers with an area of more than 1 square km. \n   - Discover the wonders of Shahdag, a land of ancient glaciers, majestic valleys, and stunning mountain lakes! Designed with avid outdoor enthusiasts in mind, Shahdag Mountain Resort offers an array of thrilling activities throughout the year. Picture yourself zooming down the slopes, feeling the crisp mountain air on your face as you carve your way through powdery snow. And for those seeking an adrenaline rush of a different kind, don''t miss the Shahdag Coaster, an exhilarating roller coaster that takes you on a wild ride through the breathtaking mountain scenery. \n   \n  15:00 - Check-in to the Hotel  \n  \n  18:00 - Dinner Break (if included) \n  \n  19:00 – Drop to Hotel \n  \n  Overnight in Shahdag', 91.0, 91.0, 114.0, 114.0, 255.0, 383.0, 504.0, 618.0, 1.0, 40.0, 65.0);
