INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (298, 'Airport Pick up', 'Gabala', 'Overnight', NULL, NULL, NULL, '- Pick-up from GYD Airport and leaving Baku to Gabala ( 1 way x 5 hrs) \n   \n 13:00 – Reaching to Gabala \n  \n  14:00 – Lunch break \n  \n  15:00 – Check-in to the Hotel \n   \n   16:00 - Visiting Tufandagh Mountains Resort  \n  - Tufandagh is a mountain peak of the Greater Caucasus range, located in the Qusar District of Azerbaijan. With an elevation of 4,191 metres (13,750 ft) above sea level, it third highest mountain in Azerbaijan. Visit to Nohur lake, guests enjoy with Panoramic Nature view (Located about 5 km. east of the Gabala city, the lake is surrounded by the forests and high mountains called Yumru, Goydag and Gulluburun. The lake covers 240 ha in total and has the maximum depth of 24 meters. The Nohur lake has very clear water thanks to the fresh water sources spilt into the lake. Apart from the small seasonal water supply coming from the mountains of Caucasus, Damiraparan and Vandam rivers also flow to the lake. \n   \n  18:00 – Dinner Break (if included) \n  \n  19:00 – Drop to the Hotel \n  \n  Overnight in Gabala', 91.0, 91.0, 114.0, 114.0, 255.0, 383.0, 504.0, 618.0, 1.0, 40.0, 65.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (299, 'Gabala', 'GYD Airport', 'Private Transfer', NULL, NULL, NULL, '09:00 am – Leaving Gabala to GYD Airport. \n   \n - Drop off at GYD Airport based on flight time.', 88.0, 88.0, 118.0, 118.0, 165.0, 295.0, 354.0, 412.0, 1.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (300, 'Hotel', 'Private Transfer', 'Private Transfer', NULL, NULL, NULL, '10:00 – Leaving Hotel Panaromic city tour which starts with panoramic full evening city view of Baku followed by: \n  - Highland Park -Which is the highest point in the Azerbaijani capital, opening a panoramic view of the city and its bay. The city''s residents and visitors often come here to see a bird''s eye view of Baku, and just have a walk. The Upland Park can be reached by cable railway (funicular) in 7-8 minutes from the boulevard or by climbing up the endless stone stairs. \n  - Flame Towers -The city''s tallest building. The height of 182 m. Flame Towers - consisting of three high-rise buildings in the complex. \n   \n  13:00 – Lunch Break \n   \n 14:00 – Shopping Tour - Guests are free to choose any of below Shopping Malls:  \n  \n  • Park Boulevard Mall \n  \n  • Port Baku Mall  \n  \n  • Ganjlik Mall \n  \n  • Nargiz Mall \n  \n  • Deniz Mall \n  \n  • 28th Mall \n  \n  • Crescent Mall \n   \n  - Drop off at GYD Airport based on flight time', 65.0, 65.0, 85.0, 85.0, 106.0, 1.0, 1.0, 1.0, 1.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (301, 'Shamakhi', 'GYD Airport', 'Private Transfer', NULL, NULL, NULL, '- Leaving Shamakhi to GYD Airport. \n  \n - Drop off at GYD Airport based on flight time.', 41.0, 47.0, 53.0, 65.0, 165.0, 236.0, 295.0, 354.0, 354.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (302, 'Sheki', 'Laqodexi', '1 way Transfer', NULL, NULL, NULL, '- Leaving Sheki to Laqodexi  \n - Drop off at Laqodexi (border area) based on required timing.', 41.0, 47.0, 53.0, 65.0, 165.0, 236.0, 295.0, 354.0, 354.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (303, 'Baku', 'Sheki', 'Overnight', NULL, NULL, NULL, '09:00 – Leaving Baku to Gobustan (1 way x 45 mins) \n  \n 10:00 – Reaching to Gobustan \n Visit Gobustan National Park, a UNESCO World Heritage site known for its ancient petroglyphs, rock formations, and archaeological heritage dating back more than 40,000 years. The open-air museum offers insights into prehistoric human life, hunting traditions, and early settlements. After exploring the site, continue to the nearby Mud Volcanoes—one of the largest mud volcano fields in the world. The unique grey, lunar-like landscape and constantly bubbling mud pools create an unforgettable natural experience and an excellent spot for photos. \n  \n 11:00 – Leaving Gobustan to Sheki (1 way x 4.5 hrs) \n  \n 13:30 – Lunch Break \n  \n 15:00 – Check-in to the Hotel                                                                                                                                                                                                                                                                                          \n  \n 16:00 -Visit Church of Kish \n - Kish is one of the oldest villages in present-day Azerbaijan and is most known for the ancient Church of Saint Elisha from the period of Caucasian Albania. The current structure was built between the 10th–12th centuries. According to scholars, it stands on the original site where St. Elisha founded the first Christian church in the region, making it one of the earliest spiritual centers in the Caucasus. \n  \n 17:00 – Visit Sheki Fortress \n - Sheki Fortress was constructed to protect the historic center, which is now recognized as a UNESCO World Heritage Site. The original fortification walls once reached 8 meters in height and 2 meters in thickness, with defensive towers and arched gates. Although parts were destroyed, several sections have been preserved and restored. \n  \n 17:00 – Explore Sheki Karavansaray \n - This historic caravanserai served as a secure lodging place for merchants traveling along the Silk Road with their animals and trade goods. Today, it stands as one of the most iconic and culturally significant architectural landmarks in Sheki. \n  \n 18:00 Traditional Sheki Halva Tasting \n Experience Sheki’s famous halva — one of the region’s most well-known traditional sweets. It remains a highlight of local cuisine and a must-try specialty for visitors. \n  \n 18:30 – Dinner break (if included) \n  \n 19:30 – Drop at the Hotel \n  \n Overnight in Sheki', 113.0, 119.0, 137.0, 148.0, 325.0, 442.0, 709.0, 677.0, 677.0, 40.0, 65.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (304, 'Baku', 'Baku', 'Day trip', NULL, NULL, NULL, '08:00 – Depart from Baku to Sheki (1 way x 5,5 hrs) \n  \n  12:30 – Lunch Break \n   \n 14:00 - Reaching to Sheki, visiting following places:   \n - Church of Kish - Kish is one of the oldest villages in present-day Azerbaijan and is most known for the ancient Church of Saint Elisha from the period of Caucasian Albania. The current structure was built between the 10th–12th centuries. According to scholars, it stands on the original site where St. Elisha founded the first Christian church in the region, making it one of the earliest spiritual centers in the Caucasus. \n - Visit Sheki Fortress - Sheki Fortress was constructed to protect the historic center, which is now recognized as a UNESCO World Heritage Site. The original fortification walls once reached 8 meters in height and 2 meters in thickness, with defensive towers and arched gates. Although parts were destroyed, several sections have been preserved and restored. \n - Explore Sheki Karavansaray - This historic caravanserai served as a secure lodging place for merchants traveling along the Silk Road with their animals and trade goods. Today, it stands as one of the most iconic and culturally significant architectural landmarks in Sheki. \n - Traditional Sheki Halva Tasting - Experience Sheki’s famous halva — one of the region’s most well-known traditional sweets. It remains a highlight of local cuisine and a must-try specialty for visitors. \n  \n  18:00 – Leaving Sheki to Baku (1 way x 5,5 hrs) \n  \n 19:30 Dinner break (if included) \n  \n 23:00 – Drop at the Hotel \n  \n Overnight in Baku', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (305, 'Hotel', 'Baku', 'Day trip', NULL, NULL, NULL, '10:00 – Leaving Hotel to Boulevard tour \n  - Baku boulevard tour starts along the Baku Boulevard followed by:  \n   \n -Carpet Museum  \n  \n  -Mini Venice of Baku \n  \n  -Deniz Mall  \n  \n  -Ferries Wheel  \n  \n  -Carpet Museums \n  \n  -Cristal Hall \n  \n  14:00 - Old City tour starts from Shamakhi Gates followed by below places (Photo stop): \n  - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture. \n  - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist. \n  - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade. \n  - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture. \n  - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City. \n  - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher. \n  - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books. \n  - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture. \n   \n  13:00 - Lunch Break \n   \n  18:00 – Dinner Break (if included) \n  \n  19:00 –Drop to Hotel \n  \n  Overnight in Baku', 35.0, 35.0, 47.0, 47.0, 71.0, 1.0, 1.0, 1.0, 1.0, 20.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (306, 'Hotel', 'Baku', 'Day trip', NULL, NULL, NULL, '14:00 – Leaving Hotel to Boulevard tour \n  Baku boulevard tour starts along the Seaside (Photostop) followed by:  \n  - Carpet Museum  \n  - Mini Venice of Baku \n  - Deniz Mall  \n  - Ferries Wheel  \n  - Carpet Museums \n  - Cristal Hall \n   \n 15:30 - Old City tour starts from Shamakhi Gates followed by below places (Photo stop): \n  - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture. \n  - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist. \n  - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade. \n  - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture. \n  - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City. \n  - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher. \n  - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books. \n  - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture. \n   \n  18:00 – Dinner Break (if included) \n  \n  19:00 –Drop to Hotel \n  \n  Overnight in Baku', 35.0, 35.0, 47.0, 47.0, 71.0, 1.0, 1.0, 1.0, 1.0, 20.0, 47.0);
