INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (350, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape \n  Rock paintings of Gobustan were first discovered in 1939  \n  by archaeologist I. Jafarzade. On this territory there are  \n  many traces of primitive inhabitance of people belong to \n   the period of the Paleolithic and Mesolithic. Rock  \n  engravings of Gobustan cover a long historical period  \n  nearly 15,000 years. In the Gobustan can be found rock \n   paintings created in the primitive epoch and up to the  \n  \\Middle Ages, nowadays there are about 6,000 drawings.  \n  The territory of Gobustan had favorable living conditions  \n  in the Mesolithic, Neolithic and Bronze Age and was \n   inhabited by hunters and fishermen. Petroglyphs of the \n   Gobustan museum included to the UNESCO World Heritage List. + Old City tour starts from Shamakhi Gates followed by Old city below places (Photo stop) \n  -Shamakhi Gates \n  -Sculptures of Azim Azimzadeh’s \n  -Caravanserai of Bukhara \n  -Caravanserai of Multani \n  -Maiden’s Tower \n  -Bazar Square \n  -Miniature Books’ Museum \n  -Shirvanshahs’ Palace', 41.0, 47.0, 47.0, 59.0, 30.0, 118.0, NULL, NULL, NULL, 12.0, 42.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (351, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape \n  Rock paintings of Gobustan were first discovered in 1939  \n  by archaeologist I. Jafarzade. On this territory there are  \n  many traces of primitive inhabitance of people belong to \n   the period of the Paleolithic and Mesolithic. Rock  \n  engravings of Gobustan cover a long historical period  \n  nearly 15,000 years. In the Gobustan can be found rock \n   paintings created in the primitive epoch and up to the  \n  \\Middle Ages, nowadays there are about 6,000 drawings.  \n  The territory of Gobustan had favorable living conditions  \n  in the Mesolithic, Neolithic and Bronze Age and was \n   inhabited by hunters and fishermen. Petroglyphs of the \n   Gobustan museum included to the UNESCO World Heritage List. + Nizami Street in Baku is an absolute must-visit! The vibrant atmosphere, beautifully lit streets, and a mix of modern and historic architecture create an unforgettable experience. It’s perfect for a leisurely stroll, shopping at high-end boutiques, or enjoying a meal at one of the many cafes and restaurants. The street truly comes alive in the evening, with its lively vibe and gorgeous lighting. Whether you’re a tourist or a local, Nizami Street offers something for everyone.', 41.0, 47.0, 47.0, 59.0, 30.0, 118.0, NULL, NULL, NULL, 12.0, 42.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (352, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape \n  Rock paintings of Gobustan were first discovered in 1939  \n  by archaeologist I. Jafarzade. On this territory there are  \n  many traces of primitive inhabitance of people belong to \n   the period of the Paleolithic and Mesolithic. Rock  \n  engravings of Gobustan cover a long historical period  \n  nearly 15,000 years. In the Gobustan can be found rock \n   paintings created in the primitive epoch and up to the  \n  \\Middle Ages, nowadays there are about 6,000 drawings.  \n  The territory of Gobustan had favorable living conditions  \n  in the Mesolithic, Neolithic and Bronze Age and was \n   inhabited by hunters and fishermen. Petroglyphs of the \n   Gobustan museum included to the UNESCO World Heritage List. + Walking tour starts along the Baku Boulevard followed by: -Mini Venice of Baku \n  -Carpet Museum -Deniz Mall  \n  -Ferries Wheel ride  \n  -Carpet Museums \n  -Boat cruise  \n  -Cristal Hall \n  -Biking Area', 41.0, 47.0, 47.0, 59.0, 30.0, 118.0, NULL, NULL, NULL, 12.0, 42.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (353, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape \n  Rock paintings of Gobustan were first discovered in 1939  \n  by archaeologist I. Jafarzade. On this territory there are  \n  many traces of primitive inhabitance of people belong to \n   the period of the Paleolithic and Mesolithic. Rock  \n  engravings of Gobustan cover a long historical period  \n  nearly 15,000 years. In the Gobustan can be found rock \n   paintings created in the primitive epoch and up to the  \n  \\Middle Ages, nowadays there are about 6,000 drawings.  \n  The territory of Gobustan had favorable living conditions  \n  in the Mesolithic, Neolithic and Bronze Age and was \n   inhabited by hunters and fishermen. Petroglyphs of the \n   Gobustan museum included to the UNESCO World Heritage List. + Panoramic City Tour starts with panoramic full evening city view of Baku followed by: \n   \n  -Highland Park (Which is the highest point in the Azerbaijani capital,  \n  opening a panoramic view of the city and its bay. The city''s residents \n  and visitors often come here to see a bird''s eye view of Baku, and  \n  just have a walk. The Upland Park can be reached by cable railway  \n  (funicular) in 7-8 minutes from the boulevard or by climbing up the \n   endless stone stairs.) \n   \n  -Flame Towers (The city''s tallest building. The height of 182 m.  \n  Flame Towers - consisting of three high-rise buildings in the complex.)', 41.0, 47.0, 47.0, 59.0, 30.0, 118.0, NULL, NULL, NULL, 12.0, 42.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (354, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape \n  Rock paintings of Gobustan were first discovered in 1939  \n  by archaeologist I. Jafarzade. On this territory there are  \n  many traces of primitive inhabitance of people belong to \n   the period of the Paleolithic and Mesolithic. Rock  \n  engravings of Gobustan cover a long historical period  \n  nearly 15,000 years. In the Gobustan can be found rock \n   paintings created in the primitive epoch and up to the  \n  \\Middle Ages, nowadays there are about 6,000 drawings.  \n  The territory of Gobustan had favorable living conditions  \n  in the Mesolithic, Neolithic and Bronze Age and was \n   inhabited by hunters and fishermen. Petroglyphs of the \n   Gobustan museum included to the UNESCO World Heritage List. + Visit to Heydar Aliyev Center for PHOTO SHOOTING  \n   & “I LOVE BAKU” sign for PHOTOSTOP (entry to Vintage Car Museums) \n  (If it’s first time of your arrival to Baku, just be aware of  \n  that from the bird view you can clearly see the Heydar  \n  Aliyev’s Signature on the Heydar Aliyev’s Center design.  \n  It’s a wave-like building rises from a bed of concrete. \n  Its immobile white walls look as though they have been  \n  frozen mid-ripple. The abstract architecture is unlike anything  \n  else in the capital city. The Heydar Aliyev Center, which was  \n  designed by renowned architect Zaha Hadid.)', 41.0, 47.0, 47.0, 59.0, 30.0, 118.0, NULL, NULL, NULL, 12.0, 42.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (355, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape \n  Rock paintings of Gobustan were first discovered in 1939  \n  by archaeologist I. Jafarzade. On this territory there are  \n  many traces of primitive inhabitance of people belong to \n   the period of the Paleolithic and Mesolithic. Rock  \n  engravings of Gobustan cover a long historical period  \n  nearly 15,000 years. In the Gobustan can be found rock \n   paintings created in the primitive epoch and up to the  \n  \\Middle Ages, nowadays there are about 6,000 drawings.  \n  The territory of Gobustan had favorable living conditions  \n  in the Mesolithic, Neolithic and Bronze Age and was \n   inhabited by hunters and fishermen. Petroglyphs of the \n   Gobustan museum included to the UNESCO World Heritage List. + Ateshgah - Fire Temple Tour (ENTRANCE) \n  (Fire temple was firmly established by the time of the  \n  Parthian Empire (247 BCE - 224 CE) and reached  \n  their height of sophistication in the time of the  \n  Sassanian Empire (224-651 CE). After the fall of  \n  the Sassanians to the Muslim Arab Invasion of 651 CE,  \n  fire temples were destroyed or converted into mosques. \n   Zoroastrians are said to have kept some of the flames  \n  from these temples burning in secret, however, and these were used to light the fires in later temples, notably those of the Parsees of India who preserved the Zoroastrian traditions and established fire temples later in that country. + A 10 m long wall of fire is never extinguishing.  \n  It is burning continuously alongside the edge of the hill.  \n  The scene is naturally is at its most spectacular at night.  \n  The height of the flames changes, but in some moments \n   it reach to 3 meters (9.8 ft) from the ground. Yanar Dag  \n  is now a protected site and there are extensive archaeological studies are going on. Local lore states that it was a shepherd that accidentally ignited the fire in the 1950s by tossing a cigarette, and that it has burnt ever since.)', 36.0, 41.0, 47.0, 59.0, 36.0, 130.0, NULL, NULL, NULL, 12.0, 42.0);
