INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (394, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Nizami Street in Baku is an absolute must-visit! The vibrant atmosphere, beautifully lit streets, and a mix of modern and historic architecture create an unforgettable experience. It’s perfect for a leisurely stroll, shopping at high-end boutiques, or enjoying a meal at one of the many cafes and restaurants. The street truly comes alive in the evening, with its lively vibe and gorgeous lighting. Whether you’re a tourist or a local, Nizami Street offers something for everyone. + Having a real and safe racing experience regardless of the  \n  weather conditions are possible with Deniz Karting''s two  \n  indoor racing tracks. The 2-story 460 m long racing tracks  \n  for adults and the 101 m long racing tracks for children are  \n  ready to give you the experience. Get ready to enjoy the \n   unique views of Baku while you race.', 30.0, 36.0, 38.0, 50.0, 30.0, 89.0, NULL, NULL, NULL, 12.0, 42.0);
