INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (396, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Walking tour starts along the Baku Boulevard followed by: -Mini Venice of Baku \n  -Carpet Museum -Deniz Mall  \n  -Ferries Wheel ride  \n  -Carpet Museums \n  -Boat cruise  \n  -Cristal Hall \n  -Biking Area + Panoramic City Tour starts with panoramic full evening city view of Baku followed by: \n   \n  -Highland Park (Which is the highest point in the Azerbaijani capital,  \n  opening a panoramic view of the city and its bay. The city''s residents \n  and visitors often come here to see a bird''s eye view of Baku, and  \n  just have a walk. The Upland Park can be reached by cable railway  \n  (funicular) in 7-8 minutes from the boulevard or by climbing up the \n   endless stone stairs.) \n   \n  -Flame Towers (The city''s tallest building. The height of 182 m.  \n  Flame Towers - consisting of three high-rise buildings in the complex.)', 30.0, 36.0, 38.0, 50.0, 30.0, 89.0, NULL, NULL, NULL, 12.0, 42.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (397, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Walking tour starts along the Baku Boulevard followed by: -Mini Venice of Baku \n  -Carpet Museum -Deniz Mall  \n  -Ferries Wheel ride  \n  -Carpet Museums \n  -Boat cruise  \n  -Cristal Hall \n  -Biking Area + Visit to Heydar Aliyev Center for PHOTO SHOOTING  \n   & “I LOVE BAKU” sign for PHOTOSTOP (entry to Vintage Car Museums) \n  (If it’s first time of your arrival to Baku, just be aware of  \n  that from the bird view you can clearly see the Heydar  \n  Aliyev’s Signature on the Heydar Aliyev’s Center design.  \n  It’s a wave-like building rises from a bed of concrete. \n  Its immobile white walls look as though they have been  \n  frozen mid-ripple. The abstract architecture is unlike anything  \n  else in the capital city. The Heydar Aliyev Center, which was  \n  designed by renowned architect Zaha Hadid.)', 30.0, 36.0, 38.0, 50.0, 30.0, 89.0, NULL, NULL, NULL, 12.0, 42.0);
